#define PI 3.14159265358979323846
vec3 xyzTtor(vec3 u)
{
    vec2 v = vec2(log(length(u.xz)),u.y);
    return vec3(atan(u.z,u.x),atan(v.y,v.x),log(length(v)));
}
vec3 torTxyz(vec3 u)
{
    vec2 w = cos(u.y-vec2(0,.5)*PI)*exp(u.z);
    vec2 v = cos(u.x-vec2(0,.5)*PI)*exp(w.x);
    return vec3(v.x,w.y,v.y);
}
vec4 nrm4(vec4 a)
{
    float l = length(a);
    vec4 r = a;
    if(l!=0.){r = a/l;}
    return r;
}
vec2 mainSound( int samp, float time )
{
    float gld = 1.618033988;
    vec4  gsu = vec4(1,1,1,1)/(2.-1./gld);
    int   bz = 5;
    vec4 baba[] = vec4[](
        //vec4(0,0,0.6124,0),
        //vec4(-0.2887,-0.5,-0.2041,0),
        //vec4(-0.2887,0.5,-0.2041,0),
        //vec4(0.5774,0,-0.2041,0)

        vec4(2,0,0,0)-gsu,
        vec4(0,2,0,0)-gsu,
        vec4(0,0,2,0)-gsu,
        vec4(0,0,0,2)-gsu,
        vec4(gld,gld,gld,gld)-gsu
    );
    vec4 p = (vec4(1)*float(samp)/iSampleRate/float(60)*2.-1.)*1.+vec4(1)*.0;
    for(int i=0; i<(1<<4); i++)
    {
        int   r1 = (i+0)%bz;
        int   r2 = (i+1)%bz;
        int   r3 = (i+2)%bz;
        vec4  v1 =        p-baba[r1];
        vec4  v2 = baba[r2]-baba[r1];
        vec4  v3 = baba[r3]-baba[r1];
        vec4  c1 = nrm4(v2);
        vec4  c2 = v3;
              c2 = c2-c1*dot(c1,c2);
              c2 = nrm4(c2);
        vec4  c3 = v1;
              c3 = c3-c1*dot(c1,c3);
              c3 = c3-c2*dot(c2,c3);
              c3 = nrm4(c3);
        float tm = -3.712;
        vec3   u = vec3(dot(v1,c1),
                        dot(v1,c2),
                        dot(v1,c3));
        vec4  cc = abs(nrm4(vec4(u,0)));
        u = xyzTtor(u);    u *= vec3(-1,1,1)*tm;
        u = torTxyz(u);    u = u+vec3(1)*1.288;
        p = baba[r1] + c1*u.x  + c2*u.y + c3*u.z;
        float lm = 2.;
        float pl = length(p);  if(pl>lm){p = p/pl*fract(pl);}
    }
    return p.xy*.2;
}
